query:
// [1] project - disease to protein graph
MATCH (source:disease)
OPTIONAL MATCH (source)-[r:disease_protein]-(target:gene_protein)
RETURN gds.graph.project(
  'diseaseToProteinGraph',
  source,
  target,
  { relationshipProperties: r { strength: 1 } }
)

// [2] estimate - disease to protein graph
CALL gds.nodeSimilarity.write.estimate('diseaseToProteinGraph', {
  writeRelationshipType: 'SIMILAR',
  writeProperty: 'score'
})
YIELD nodeCount, relationshipCount, bytesMin, bytesMax, requiredMemory

// copper drug node
MATCH(n:drug { node_index: '14012' })
RETURN n

// mullerian disease node
MATCH(n:disease { node_index: '27165'})
RETURN n

// Crohn disease
MATCH(n:disease {node_name: "Crohn disease"})
RETURN n

// Crohn's colitis
MATCH(n:disease {node_name: "Crohn's colitis"})
RETURN n

// lupus erythematosus disease
MATCH(n:disease {node_name: "lupus erythematosus"})
RETURN n

// Match FOXP transciptomics protein
MATCH (n:gene_protein { node_name: 'FOXP3'})
RETURN n

// delete all csl tpp and relationships
MATCH p=(n:csl_tpp)-[]-(n2)
delete p

// query for patents related to a given csl tpp
MATCH (n:csl_tpp { node_id: 'dd485875e4b59bc35883471d7fc9f01d' })
CALL db.index.vector.queryNodes('pgpub_embeddings_index', 200, n.embeddings)
YIELD node, score
RETURN score, n.product_description as tpp_description, node.application_number_text as patent_application_no, node.abstract as patent_abstract, node.claims as patent_claims;

// match path for lupus and ae-941
MATCH p=(n1 {node_index: '94775'})-[r1]-(p1:gene_protein)-[r2]-(n2 {node_index: '16198'})
RETURN p

// pubmed extraction count
MATCH (doc:pubmed_document)-[extraction:has_extraction]-()
RETURN doc.pmcid, COUNT(extraction) as count ORDER BY count DESC

// pubmed level 4 summaries
MATCH path=(doc:pubmed_document { pmcid: '11788946'})-[rel:has_summary]-(summary:pubmed_summary { level: 4})
RETURN path

// pubmed with extractions gvhd 
MATCH path=(doc:pubmed_document {pmcid: '11781120'})-[rel:has_extraction]-()
RETURN path

// pubmed with summaries
MATCH path=(doc:pubmed_document {pmcid: '11782851'})-[rel:has_summary]-()
RETURN path

// pubmed with summaries gvhd 
MATCH path=(doc:pubmed_document {pmcid: '11781120'})-[rel:has_summary]-()
RETURN path

// Count nodes
MATCH (n)
RETURN count(n) as count

// Delete All
MATCH (n)
DETACH DELETE n

// graph density
CALL apoc.meta.stats() YIELD nodeCount, relCount
RETURN toFloat(relCount) / (nodeCount * (nodeCount - 1)) as density

// list models
CALL gds.model.list()
YIELD modelName, modelType, modelInfo, loaded, stored, published

// list query runtimes
SHOW TRANSACTIONS YIELD transactionId, runtime, currentQueryElapsedTime ORDER BY transactionId
RETURN transactionId, runtime, currentQueryElapsedTime

// Match nodes
MATCH (n)
RETURN n

// Match relationships
MATCH p=(n1)-[r]->(n2)
RETURN p

// project protein graph
MATCH (source:gene_protein)
OPTIONAL MATCH (source:gene_protein)-[r:protein_protein]->(target:gene_protein)
RETURN gds.graph.project(
  'persons',
  source,
  target,
  {
    sourceNodeLabels: labels(source),
    targetNodeLabels: labels(target),
    sourceNodeProperties: source { .node_name },
    targetNodeProperties: target { .node_name },
    relationshipType: type(r),
    relationshipProperties: r { .relWeight }
  },
  { undirectedRelationshipTypes: ['drug_protein', 'protein_protein'] }
)

// pubmed with summaries
MATCH path=(doc:pubmed_document {pmcid: '11788946', level: 2})-[rel:has_summary]-()
RETURN path

// Show protein relationships
MATCH p=(n1)-[r:protein_protein]->(n2)
RETURN p
